/**
 * Normalize the backend's order-list response (ReadableOrderList:
 * { orders, pageCount, itemsOnPage, totalRecords, recordsFiltered })
 * into { orders, pages, total, onThisPage }.
 */
export function normalizeOrderList(response) {
  const data = response && typeof response === \"object\" ? response : {};

  const orders = Array.isArray(data.orders) ? data.orders : [];

  const toInt = (value) => {
    const n = Number(value);
    return Number.isFinite(n) ? n : 0;
  };

  return {
    orders,
    pages: toInt(data.pageCount),
    total: toInt(data.totalRecords),
    onThisPage: toInt(data.itemsOnPage),
  };
}
EOF
